<?php
// SPDX-License-Identifier: AGPL-3.0-only
use Panel\Services\{DnsMode,Transfer,DomainConfig};
use Panel\Core\Validator;

$db->run("DELETE FROM settings WHERE name='preview_mode'");
$db->run("UPDATE jobs SET status='cancelled' WHERE status NOT IN ('completed','cancelled')");
$db->run('UPDATE domains SET next_check_at=NULL');
$modeEntry=$configs->save('entries',['name'=>'Mode test preferred','kind'=>'cname','targets'=>['mode.edge.test']],'test');
$modeInput=['name'=>'mode','type'=>'A','source_ip'=>'9.9.9.10','dns_mode'=>'dns_only','profile_id'=>$profile,'entry_id'=>$modeEntry,'check'=>['path'=>'/','statuses'=>[200],'keyword'=>'']];
$saasCalls=count($saas->requests);
$createdMode=$zoneRecords->create($customerZone,$modeInput,'test');$modeId=$createdMode['items'][0]['domain_id'];tick($worker,$db,3);
$modeDetail=$service->detail($modeId);$modeDns=array_values(array_filter($dns->records,fn($r)=>$r['name']==='mode.customer.test'));
check($modeDetail['status']==='active'&&$modeDetail['dns_mode']==='dns_only'&&$modeDetail['cf_hostname_id']===null,'gray-cloud record activates without a SaaS hostname');
check(count($saas->requests)===$saasCalls&&count($modeDns)===1&&$modeDns[0]['type']==='A'&&$modeDns[0]['content']==='9.9.9.10'&&!$modeDns[0]['proxied'],'gray cloud writes direct source DNS without contacting the SaaS account');
check($modeDetail['cleanup_status']==='not_required'&&$modeDetail['next_check_at']===null,'ordinary DNS records do not schedule SaaS verification or certificate renewal');
rejects(fn()=>$service->configure($modeId,['dns_mode'=>'invalid'],'test'),422,'invalid DNS mode rejected');
$legacy=['origin'=>['source_ip'=>'9.9.9.10']];check(DnsMode::of($legacy)==='preferred','snapshots without a DNS mode remain preferred');
$previousEntry=$modeDetail['applied_config']['entry'];$configs->update('entries',$modeEntry,['targets'=>['edited.mode.edge.test']],'test');
$service->configure($modeId,['dns_mode'=>'proxied','expected_version'=>$modeDetail['config_version']],'test');tick($worker,$db,3);
$orange=$service->detail($modeId);$orangeDns=array_values(array_filter($dns->records,fn($r)=>$r['name']==='mode.customer.test'));
check($orange['dns_mode']==='proxied'&&$orangeDns[0]['proxied']&&$orangeDns[0]['ttl']===1,'orange-cloud mode enables proxying and automatic TTL on the source IP');
check($orange['applied_config']['entry']===$previousEntry&&count($saas->requests)===$saasCalls,'mode-only switch preserves the applied preferred preset and avoids SaaS writes');
$service->action($modeId,'rollback','test');tick($worker,$db);
check($service->detail($modeId)['dns_mode']==='dns_only'&&!array_values(array_filter($dns->records,fn($r)=>$r['name']==='mode.customer.test'))[0]['proxied'],'mode rollback restores the gray-cloud state');
$saas->ready=false;$saas->includeOwnership=true;
$service->configure($modeId,['dns_mode'=>'preferred'],'test');tick($worker,$db,3);
check($service->detail($modeId)['status']==='changing'&&(int)$db->value("SELECT COUNT(*) FROM verification_records WHERE domain_id=? AND status='present'",[$modeId])===2,'first switch to preferred provisions SaaS and waits for TXT validation');
$saas->ready=true;tick($worker,$db,4);
$preferred=$service->detail($modeId);$preferredDns=array_values(array_filter($dns->records,fn($r)=>$r['name']==='mode.customer.test'));
check($preferred['status']==='active'&&$preferred['dns_mode']==='preferred'&&$preferredDns[0]['type']==='CNAME'&&$preferredDns[0]['content']==='mode.edge.test'&&!$preferredDns[0]['proxied'],'preferred mode activates the saved optimized entry after certificate validation');
check((int)$db->value("SELECT COUNT(*) FROM verification_records WHERE domain_id=? AND status='deleted'",[$modeId])===2,'preferred activation cleans its owned temporary TXT records');
$retainedHost=$preferred['cf_hostname_id'];$oldRemote=$saas->hostnames[$retainedHost]['custom_origin_server'];
$service->configure($modeId,['dns_mode'=>'dns_only'],'test');tick($worker,$db,3);
check(isset($saas->hostnames[$retainedHost])&&$service->detail($modeId)['dns_mode']==='dns_only','leaving preferred mode keeps the managed SaaS hostname available for restoration');
$callsBeforeDirectEdit=count($saas->requests);$service->configure($modeId,['source_ip'=>'8.8.8.8'],'test');tick($worker,$db,3);
check($service->detail($modeId)['applied_config']['origin']['source_ip']==='8.8.8.8'&&count($saas->requests)===$callsBeforeDirectEdit&&$saas->hostnames[$retainedHost]['custom_origin_server']===$oldRemote,'direct source edits change visitor DNS while retaining the previous SaaS origin');
$service->configure($modeId,['dns_mode'=>'preferred'],'test');tick($worker,$db,4);
check($service->detail($modeId)['dns_mode']==='preferred'&&$saas->hostnames[$retainedHost]['custom_origin_server']!==$oldRemote,'returning to preferred updates the retained hostname to the new source');
$service->action($modeId,'rollback','test');tick($worker,$db);
check($service->detail($modeId)['dns_mode']==='dns_only'&&array_values(array_filter($dns->records,fn($r)=>$r['name']==='mode.customer.test'))[0]['content']==='8.8.8.8','rollback from preferred restores the previous direct source and proxy state');
$service->configure($modeId,['dns_mode'=>'preferred','check'=>['keyword'=>'force-fail']],'test');tick($failureWorker,$db,5);
check($service->detail($modeId)['status']==='active'&&$service->detail($modeId)['dns_mode']==='dns_only','failed preferred activation automatically restores ordinary DNS mode');
$modeExport=$transfer->export($customerZone);$modePlan=array_values(array_filter($modeExport['records'],fn($r)=>$r['hostname']==='mode.customer.test'))[0];
check($modeExport['format_version']===2&&$modePlan['dns_mode']==='dns_only','non-preferred mode export uses a format older importers will reject');
$modeExport['records']=[$modePlan];$modeExport['records'][0]['hostname']='mode-import.customer.test';
$importMode=$transfer->import(['document'=>$modeExport,'preview'=>false],'test');
check($service->detail($importMode['records'][0]['domain_id'])['dns_mode']==='dns_only','import preserves the chosen DNS mode');
$service->action($importMode['records'][0]['domain_id'],'cancel','test');
$wrongFormat=$modeExport;$wrongFormat['format_version']=1;
rejects(fn()=>$transfer->import(['document'=>$wrongFormat],'test'),422,'old export format cannot silently reinterpret a direct DNS record');
check($service->detail($modeId)['jobs'][0]['kind']==='change','mode operations retain per-change audit history');
$service->remove($modeId,['mode'=>'delete_remote'],'test');tick($worker,$db);
check(!isset($saas->hostnames[$retainedHost])&&$service->detail($modeId)['deleted_at']!==null,'removal in direct mode cleans the retained owned SaaS hostname safely');
